template<bool HaveOpenSSL>
class EnabledDebugList {
 public:
  static constexpr size_t category_count =
      non_crypto_count + (HaveOpenSSL ? crypto_count : 0) + extra_count;
  static constexpr size_t permission_category =
      non_crypto_count + (HaveOpenSSL ? crypto_count : 0) +
      static_cast<size_t>(ExtraCategory::PERMISSION_MODEL);
  bool enabled(size_t category) const { return enabled_[category]; }
  void Parse(const EnvironmentPathAccess* env) {
    EnvironmentString cats;
    SafeGetenv("NODE_DEBUG_NATIVE", &cats, env);
    Parse(cats);
  }
  void Parse(const EnvironmentString& cats) {
    EnvironmentString debug_categories = cats;
    while (!debug_categories.empty()) {
      EnvironmentString::size_type comma_pos = debug_categories.find(',');
      EnvironmentString wanted = ToLower(debug_categories.substr(0, comma_pos));
      size_t category = 0;
#define V(name)                                                               \
      {                                                                       \
        static const EnvironmentString available_category = ToLower(#name);    \
        if (available_category.find(wanted) != EnvironmentString::npos)        \
          enabled_[category] = true;                                          \
        ++category;                                                           \
      }
      PI_NODE_DEBUG_NON_CRYPTO(V)
      if constexpr (HaveOpenSSL) { PI_NODE_DEBUG_CRYPTO(V) }
      PI_NODE_DEBUG_EXTRA(V)
#undef V
      if (comma_pos == EnvironmentString::npos) break;
      debug_categories = debug_categories.substr(comma_pos + 1);
    }
  }
 private:
  bool enabled_[category_count] = {false};
};

// The C call view borrows the existing original String span. Its sole
// conversion below performs the original ToStringHelper String copy, without
// manufacturing an extra owning input String before SPrintF's ret local.
struct SizedString {
  const char* data;
  size_t length;
};
struct ToStringHelper {
  static EnvironmentString Convert(const SizedString& value) {
    return EnvironmentString(value.data, value.length);
  }
  static EnvironmentString Convert(const EnvironmentString& value) {
    return value;
  }
  static std::string_view Convert(const char* value) {
    return value != nullptr ? value : "(null)";
  }
  static std::string_view Convert(std::string_view value) { return value; }
  template<unsigned BASE_BITS, typename T>
  static auto BaseConvert(T&& value) {
    return Convert(std::forward<T>(value));
  }
};
template<typename T>
auto ToStringOrStringView(const T& value) {
  return ToStringHelper::Convert(value);
}
template<unsigned BASE_BITS, typename T>
auto ToBaseString(const T& value) {
  return ToStringHelper::BaseConvert<BASE_BITS>(value);
}

inspected_code.actual_allocator:
// Native C++ standard-container allocation for the pinned libc++ build.
// The allocation/new-handler sequence follows libc++ new.cpp (Apache-2.0
// WITH LLVM-exception); the underlying charged block owner is shared with
// the separately reviewed simdjson owner. No Engine or JS value is stored.
#ifndef PI_NATIVE_NODE_STANDARD_ALLOCATOR_HPP
#define PI_NATIVE_NODE_STANDARD_ALLOCATOR_HPP
#include "native_simdjson_memory.hpp"
#include <__new/exceptions.h>
#include <cstddef>
#include <limits>
#include <new>
#include <type_traits>

#if !defined(_LIBCPP_VERSION) || _LIBCPP_STD_VER < 20
#error "the standard-container owner requires the pinned C++20 libc++ source"
#endif
#if _LIBCPP_HAS_EXCEPTIONS
#error "the selected Node standard-container translation units disable exceptions"
#endif

namespace pi_node {
using AllocationScope = pi_simd::Scope;

// A standard allocator must not return nullptr. Preserve the actual native
// new-handler retry and bad_alloc path; this is never a JavaScript exception.
// The prefix allocator rolls a failed physical malloc reservation back before
// the handler runs. Every successful block retains its original native owner.
inline void* allocateStandard(std::size_t bytes) {
  if (bytes == 0) bytes = 1;
  for (;;) {
    if (void* result = pi_simd::allocate(bytes)) return result;
    const std::new_handler handler = std::get_new_handler();
    if (handler) handler();
    else std::__throw_bad_alloc();
  }
}

template<class T>
class Allocator {
 public:
  using value_type = T;
  using size_type = std::size_t;
  using difference_type = std::ptrdiff_t;
  using propagate_on_container_move_assignment = std::true_type;
  using is_always_equal = std::true_type;

  constexpr Allocator() noexcept = default;
  template<class U>
  constexpr Allocator(const Allocator<U>&) noexcept {}

  [[nodiscard]] T* allocate(std::size_t count) {
    static_assert(alignof(T) <= alignof(std::max_align_t),
                  "the admitted native containers use malloc-aligned elements");
    if (count > std::numeric_limits<std::size_t>::max() / sizeof(T))
      std::__throw_bad_array_new_length();
    return static_cast<T*>(allocateStandard(count * sizeof(T)));
  }
  void deallocate(T* value, std::size_t) noexcept {
    pi_simd::release(value);
  }
};

template<class T, class U>
constexpr bool operator==(const Allocator<T>&, const Allocator<U>&) noexcept {
  return true;
}
static_assert(std::is_empty_v<Allocator<char>>,
              "the allocator must not add per-string state or remove SSO");
}  // namespace pi_node
#endif

inspected_code.actual_block_owner:
// Actual per-allocation accounting for the private simdjson successor.
// The allocator domain may leave scope before a parser or one of its blocks
// retires. Each block holds its own native memory-owner entitlement.
#include "native_simdjson_memory.hpp"

extern "C" {
void pi_js_retain_memory_owner(void* memory_owner);
void pi_js_release_memory_owner(void* memory_owner);
int pi_js_native_memory_reserve(void* memory_owner, std::size_t bytes);
void pi_js_native_memory_release(void* memory_owner, std::size_t bytes);
}

namespace pi_simd {
namespace {
struct alignas(std::max_align_t) Allocation {
  void* memory_owner;
  std::size_t charge;
};
static_assert(sizeof(Allocation) % alignof(std::max_align_t) == 0,
              "the payload must retain malloc alignment");
thread_local Scope* current_scope = nullptr;
}

Scope::Scope(void* memory_owner) noexcept
    : previous_(current_scope), memory_owner_(memory_owner) {
  // This is an internal C ABI precondition. The public native parser owner
  // obtains the actual nonnull memory owner before any parser operation.
  if (!memory_owner_) std::abort();
  pi_js_retain_memory_owner(memory_owner_);
  current_scope = this;
}
Scope::~Scope() noexcept {
  if (current_scope != this) std::abort();
  current_scope = previous_;
  pi_js_release_memory_owner(memory_owner_);
}
void allocationFailure() noexcept {
  if (!current_scope) std::abort();
  current_scope->failed_ = true;
}
void* allocate(std::size_t payload) noexcept {
  Scope* scope = current_scope;
  if (!scope) std::abort();
  if (payload > std::numeric_limits<std::size_t>::max() - sizeof(Allocation)) {
    scope->failed_ = true;
    return nullptr;
  }
  const std::size_t charge = sizeof(Allocation) + payload;
  void* owner = scope->memory_owner_;
  if (!pi_js_native_memory_reserve(owner, charge)) {
    scope->failed_ = true;
    return nullptr;
  }
  auto* allocation = static_cast<Allocation*>(std::malloc(charge));
  if (!allocation) {
    // Roll back only this failed request. Existing parser blocks keep both
    // their exact charges and their independent ownership entitlements.
    pi_js_native_memory_release(owner, charge);
    scope->failed_ = true;
    return nullptr;
  }
  pi_js_retain_memory_owner(owner);
  ::new (static_cast<void*>(allocation)) Allocation{owner, charge};
  return allocation + 1;
}
void release(void* block) noexcept {
  if (!block) return;
  auto* allocation = static_cast<Allocation*>(block) - 1;
  void* owner = allocation->memory_owner;
  const std::size_t charge = allocation->charge;
  allocation->~Allocation();
  std::free(allocation);
  pi_js_native_memory_release(owner, charge);
  pi_js_release_memory_owner(owner);
}
}  // namespace pi_simd
